import { useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { fetchAnalysis, fetchDataRange, fetchPublicConfig, fetchTraffic } from "./api/client";
import "./App.css";

const INTERVAL_OPTIONS = [
  { value: "auto", label: "自动" },
  { value: 10, label: "10 分钟" },
  { value: 20, label: "20 分钟" },
  { value: 30, label: "30 分钟" },
  { value: 60, label: "60 分钟" },
  { value: 120, label: "120 分钟" },
];
const DIRECTION_OPTIONS = ["全部方向", "东向西", "西向东", "南向北", "北向南"];
const PIE_COLORS = ["#4a8fff", "#1bb58a", "#f3c145", "#6a7cff", "#ff7d4d"];

function getConfluenceView(intersections) {
  if (!intersections.length) {
    return { center: [106.506145, 29.639573], zoom: 16.8 };
  }
  const lng = intersections.reduce((s, x) => s + x.longitude, 0) / intersections.length;
  const lat = intersections.reduce((s, x) => s + x.latitude, 0) / intersections.length;
  return { center: [lng, lat], zoom: 16.8 };
}

function toApiTime(value) {
  return value ? value.replace("T", " ") : undefined;
}

function toInputTime(dateOrStr) {
  const date = new Date(dateOrStr);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (v) => `${v}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function formatBucket(ts) {
  const d = new Date(ts);
  return `${`${d.getHours()}`.padStart(2, "0")}:${`${d.getMinutes()}`.padStart(2, "0")}`;
}

function chooseAutoInterval(startInput, endInput) {
  const hours = (new Date(endInput).getTime() - new Date(startInput).getTime()) / 3600000;
  if (hours <= 3) return 10;
  if (hours <= 8) return 20;
  if (hours <= 16) return 30;
  if (hours <= 36) return 60;
  return 120;
}

function resolveInterval(mode, start, end) {
  if (mode === "auto") return chooseAutoInterval(start, end);
  return Number(mode);
}

function levelColor(value) {
  if (value >= 60) return "#e14d31";
  if (value >= 30) return "#f2bf47";
  return "#2cb985";
}

function segmentLength(vehicleCount) {
  if (vehicleCount >= 80) return 0.0012;
  if (vehicleCount >= 40) return 0.00088;
  return 0.00055;
}

function markerOffset(index) {
  const arr = [
    [0, 0],
    [10, -8],
    [-10, 8],
    [8, 9],
    [-8, -9],
  ];
  return arr[index % arr.length];
}

function getRoadAverage(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const current = grouped.get(row.site_name) || { sum: 0, n: 0 };
    current.sum += row.vehicle_count;
    current.n += 1;
    grouped.set(row.site_name, current);
  });
  const result = new Map();
  grouped.forEach((v, k) => result.set(k, v.n ? v.sum / v.n : 0));
  return result;
}

function buildDirectionData(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    grouped.set(row.approach, (grouped.get(row.approach) || 0) + row.vehicle_count);
  });
  return [...grouped.entries()].map(([name, value]) => ({ name, value }));
}

function cardStats(rows) {
  if (!rows.length) return { flow: 0, speed: 0, weather: "-" };
  return {
    flow: Math.round(rows.reduce((s, x) => s + x.vehicle_count, 0) / rows.length),
    speed: Number((rows.reduce((s, x) => s + x.avg_speed, 0) / rows.length).toFixed(1)),
    weather: rows[0].weather || "-",
  };
}

function App() {
  const [amapKey, setAmapKey] = useState("");
  const [intersections, setIntersections] = useState([]);

  const [startInput, setStartInput] = useState("");
  const [endInput, setEndInput] = useState("");
  const [timeLimit, setTimeLimit] = useState({ min: "", max: "" });
  const [applied, setApplied] = useState(null);
  const [timeCollapsed, setTimeCollapsed] = useState(false);

  const [direction, setDirection] = useState("全部方向");
  const [flowRoad, setFlowRoad] = useState("全部路口平均");
  const [speedRoad, setSpeedRoad] = useState("全部路口平均");
  const [flowIntervalMode, setFlowIntervalMode] = useState("auto");
  const [speedIntervalMode, setSpeedIntervalMode] = useState("auto");

  const [flowData, setFlowData] = useState([]);
  const [speedData, setSpeedData] = useState([]);
  const [highlightRows, setHighlightRows] = useState([]);

  const [popupVisible, setPopupVisible] = useState(false);
  const [popupRoad, setPopupRoad] = useState("");
  const [popupPos, setPopupPos] = useState({ left: 0, top: 0 });
  const [popupRows, setPopupRows] = useState([]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const AMapRef = useRef(null);
  const linesRef = useRef([]);
  const confluenceViewRef = useRef({ center: [106.506145, 29.639573], zoom: 16.8 });

  const endMin = useMemo(() => {
    if (!startInput) return timeLimit.min;
    return toInputTime(new Date(new Date(startInput).getTime() + 3600000));
  }, [startInput, timeLimit.min]);

  useEffect(() => {
    let active = true;
    async function bootstrap() {
      try {
        const [cfg, range] = await Promise.all([fetchPublicConfig(), fetchDataRange()]);
        if (!active) return;
        setAmapKey(cfg.amap_api_key);
        const sites = (cfg.intersections || []).filter((x) => x.longitude || x.latitude);
        setIntersections(sites);

        const min = toInputTime(range.min_timestamp);
        const max = toInputTime(range.max_timestamp);
        const start = min;
        const initEnd = toInputTime(new Date(new Date(start).getTime() + 3600000));
        const end = initEnd > max ? max : initEnd;
        setTimeLimit({ min, max });
        setStartInput(start);
        setEndInput(end);
        setApplied({ start, end });
      } catch (err) {
        if (!active) return;
        setError(`初始化失败：${err.message}`);
      }
    }
    bootstrap();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    if (!amapKey || !intersections.length || !mapContainerRef.current) return undefined;
    let destroyed = false;
    async function initMap() {
      try {
        const AMap = await AMapLoader.load({
          key: amapKey,
          version: "2.0",
          plugins: ["AMap.Scale"],
        });
        if (destroyed) return;
        AMapRef.current = AMap;
        const view = getConfluenceView(intersections);
        confluenceViewRef.current = view;
        const map = new AMap.Map(mapContainerRef.current, {
          center: view.center,
          zoom: view.zoom,
          viewMode: "2D",
        });
        map.addControl(new AMap.Scale());
        mapRef.current = map;

        intersections.forEach((site, idx) => {
          const off = markerOffset(idx);
          const marker = new AMap.Marker({
            position: [site.longitude, site.latitude],
            offset: new AMap.Pixel(off[0], off[1]),
            content: '<div class="road-dot"></div>',
            label: {
              direction: "top",
              content: `<div class="amap-label">${site.site_name}</div>`,
              offset: new AMap.Pixel(off[0], off[1] - 8),
            },
          });
          marker.on("click", () => openPopup(site));
          marker.setMap(map);
        });
      } catch (err) {
        setError(
          `地图加载失败：${err.message}。请确认 Web JS API key 白名单包含 localhost 和 127.0.0.1。`
        );
      }
    }
    initMap();
    return () => {
      destroyed = true;
      linesRef.current.forEach((x) => x.setMap(null));
      linesRef.current = [];
      if (mapRef.current) mapRef.current.destroy();
      mapRef.current = null;
    };
  }, [amapKey, intersections]);

  useEffect(() => {
    if (!applied) return;
    let active = true;
    async function loadMainData() {
      try {
        setLoading(true);
        setError("");
        const flowInterval = resolveInterval(flowIntervalMode, applied.start, applied.end);
        const speedInterval = resolveInterval(speedIntervalMode, applied.start, applied.end);
        const common = {
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          direction: direction === "全部方向" ? undefined : direction,
        };

        const [flowResp, speedResp, trafficResp] = await Promise.all([
          fetchAnalysis({
            ...common,
            interval_minutes: flowInterval,
            road_name: flowRoad === "全部路口平均" ? undefined : flowRoad,
          }),
          fetchAnalysis({
            ...common,
            interval_minutes: speedInterval,
            road_name: speedRoad === "全部路口平均" ? undefined : speedRoad,
          }),
          fetchTraffic({ ...common, limit: 5000 }),
        ]);
        if (!active) return;
        setFlowData((flowResp || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.bucket_start) })));
        setSpeedData((speedResp || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.bucket_start) })));
        setHighlightRows(trafficResp || []);
      } catch (err) {
        if (!active) return;
        setError(`数据加载失败：${err.message}`);
      } finally {
        if (active) setLoading(false);
      }
    }
    loadMainData();
    return () => {
      active = false;
    };
  }, [applied, direction, flowRoad, speedRoad, flowIntervalMode, speedIntervalMode]);

  useEffect(() => {
    if (!popupVisible || !popupRoad || !applied) return;
    let active = true;
    async function loadPopupData() {
      try {
        const rows = await fetchTraffic({
          road_name: popupRoad,
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          direction: direction === "全部方向" ? undefined : direction,
          limit: 5000,
        });
        if (!active) return;
        setPopupRows(rows || []);
      } catch (err) {
        if (!active) return;
        setPopupRows([]);
        setError(`路口数据加载失败：${err.message}`);
      }
    }
    loadPopupData();
    return () => {
      active = false;
    };
  }, [popupVisible, popupRoad, applied, direction]);

  const roadAvg = useMemo(() => getRoadAverage(highlightRows), [highlightRows]);
  useEffect(() => {
    if (!mapRef.current || !AMapRef.current) return;
    linesRef.current.forEach((x) => x.setMap(null));
    linesRef.current = [];

    intersections.forEach((site, idx) => {
      const avg = roadAvg.get(site.site_name) || 0;
      const len = segmentLength(avg);
      const horizontal = idx % 2 === 0;
      const p1 = horizontal
        ? [site.longitude - len / 2, site.latitude]
        : [site.longitude, site.latitude - len / 2];
      const p2 = horizontal
        ? [site.longitude + len / 2, site.latitude]
        : [site.longitude, site.latitude + len / 2];
      const line = new AMapRef.current.Polyline({
        path: [p1, p2],
        strokeColor: levelColor(avg),
        strokeWeight: 8,
        strokeOpacity: 0.92,
        lineCap: "round",
      });
      line.setMap(mapRef.current);
      linesRef.current.push(line);
    });
  }, [roadAvg, intersections]);

  const roadOptions = useMemo(
    () => ["全部路口平均", ...intersections.map((x) => x.site_name)],
    [intersections]
  );

  const popupDirectionData = useMemo(() => buildDirectionData(popupRows), [popupRows]);
  const popupStats = useMemo(() => cardStats(popupRows), [popupRows]);

  function openPopup(site) {
    if (!mapRef.current) return;
    const pixel = mapRef.current.lngLatToContainer([site.longitude, site.latitude]);
    const x = typeof pixel.getX === "function" ? pixel.getX() : pixel.x;
    const y = typeof pixel.getY === "function" ? pixel.getY() : pixel.y;
    const left = Math.max(20, Math.min(x + 24, mapContainerRef.current.clientWidth - 340));
    const top = Math.max(88, Math.min(y - 20, mapContainerRef.current.clientHeight - 220));

    setPopupRoad(site.site_name);
    setPopupVisible(true);
    setPopupPos({ left, top });
  }

  function handleConfirmTime() {
    if (!startInput || !endInput) {
      setError("请先完整选择时间。");
      return;
    }
    const start = new Date(startInput).getTime();
    const end = new Date(endInput).getTime();
    if (end - start < 3600000) {
      setError("终止时间必须至少晚于起始时间 1 小时。");
      return;
    }
    setApplied({ start: startInput, end: endInput });
  }

  function handleResetView() {
    if (!mapRef.current) return;
    mapRef.current.setCenter(confluenceViewRef.current.center);
    mapRef.current.setZoom(confluenceViewRef.current.zoom);
  }

  function handleZoomIn() {
    if (!mapRef.current) return;
    mapRef.current.setZoom(mapRef.current.getZoom() + 1);
  }

  function handleZoomOut() {
    if (!mapRef.current) return;
    mapRef.current.setZoom(mapRef.current.getZoom() - 1);
  }

  return (
    <div className="app-shell">
      <div className="main-layout">
        <section className="left-map-panel">
          <div className="panel-title">实时流量地图</div>
          <div className={`time-card ${timeCollapsed ? "collapsed" : ""}`}>
            <button
              type="button"
              className="collapse-btn"
              title={timeCollapsed ? "展开时间选择器" : "收起时间选择器"}
              onClick={() => setTimeCollapsed((v) => !v)}
            >
              {timeCollapsed ? "▾" : "▴"}
            </button>
            {!timeCollapsed ? (
              <>
                <label>起始时间</label>
                <input
                  type="datetime-local"
                  min={timeLimit.min}
                  max={timeLimit.max}
                  value={startInput}
                  onChange={(e) => {
                    const v = e.target.value;
                    setStartInput(v);
                    const minEnd = new Date(new Date(v).getTime() + 3600000);
                    if (endInput && new Date(endInput).getTime() < minEnd.getTime()) {
                      setEndInput(toInputTime(minEnd));
                    }
                  }}
                />
                <label>终止时间</label>
                <input
                  type="datetime-local"
                  min={endMin}
                  max={timeLimit.max}
                  value={endInput}
                  onChange={(e) => setEndInput(e.target.value)}
                />
                <button type="button" className="confirm-btn" onClick={handleConfirmTime}>
                  确定
                </button>
              </>
            ) : null}
          </div>

          <div className="map-controls">
            <button type="button" title="放大" onClick={handleZoomIn}>
              +
            </button>
            <button type="button" title="缩小" onClick={handleZoomOut}>
              -
            </button>
            <button type="button" title="恢复默认视图" onClick={handleResetView}>
              ⌂
            </button>
          </div>

          <div className="map-frame" ref={mapContainerRef} />

          {popupVisible ? (
            <div className="road-popup" style={{ left: `${popupPos.left}px`, top: `${popupPos.top}px` }}>
              <button type="button" className="popup-close" onClick={() => setPopupVisible(false)}>
                ×
              </button>
              <div className="popup-head">
                <h3>{popupRoad}</h3>
                <span>{popupStats.weather}</span>
              </div>
              <div className="popup-metrics">
                <div>
                  <label>总车流量</label>
                  <strong>{popupStats.flow}</strong>
                </div>
                <div>
                  <label>平均车速</label>
                  <strong>{popupStats.speed} km/h</strong>
                </div>
              </div>
              <div className="popup-body">
                <ResponsiveContainer width="48%" height={136}>
                  <PieChart>
                    <Pie data={popupDirectionData} dataKey="value" nameKey="name" innerRadius={28} outerRadius={52}>
                      {popupDirectionData.map((item, idx) => (
                        <Cell key={item.name} fill={PIE_COLORS[idx % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <div className="dir-list">
                  {popupDirectionData.map((item, idx) => (
                    <div key={item.name} className="dir-item">
                      <span className="dir-dot" style={{ backgroundColor: PIE_COLORS[idx % PIE_COLORS.length] }} />
                      <span>{item.name}</span>
                      <strong>{item.value}</strong>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : null}
        </section>

        <aside className="right-panel">
          <section className="section-block">
            <h2>数据分析展示</h2>
            <div className="toolbar-row">
              <select value={direction} onChange={(e) => setDirection(e.target.value)}>
                {DIRECTION_OPTIONS.map((x) => (
                  <option key={x} value={x}>
                    {x}
                  </option>
                ))}
              </select>
              <span className="range-text">
                {applied ? `${applied.start.replace("T", " ")} ~ ${applied.end.replace("T", " ")}` : "-"}
              </span>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车流量柱状图</h3>
                <div className="chart-controls">
                  <select value={flowIntervalMode} onChange={(e) => setFlowIntervalMode(e.target.value)}>
                    {INTERVAL_OPTIONS.map((op) => (
                      <option key={`f-${op.value}`} value={op.value}>
                        {op.label}
                      </option>
                    ))}
                  </select>
                  <select value={flowRoad} onChange={(e) => setFlowRoad(e.target.value)}>
                    {roadOptions.map((name) => (
                      <option key={`fr-${name}`} value={name}>
                        {name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={240}>
                <BarChart data={flowData} margin={{ left: -10, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis width={36} />
                  <Tooltip />
                  <Bar dataKey="vehicle_count" fill="#3f89ff" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车速折线图</h3>
                <div className="chart-controls">
                  <select value={speedIntervalMode} onChange={(e) => setSpeedIntervalMode(e.target.value)}>
                    {INTERVAL_OPTIONS.map((op) => (
                      <option key={`s-${op.value}`} value={op.value}>
                        {op.label}
                      </option>
                    ))}
                  </select>
                  <select value={speedRoad} onChange={(e) => setSpeedRoad(e.target.value)}>
                    {roadOptions.map((name) => (
                      <option key={`sr-${name}`} value={name}>
                        {name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={240}>
                <LineChart data={speedData} margin={{ left: -12, right: 6 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis width={36} />
                  <Tooltip />
                  <Line type="monotone" dataKey="avg_speed" stroke="#21b88f" strokeWidth={2.4} dot={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </section>

          <section className="section-block">
            <h2>预测</h2>
            <div className="dev-card">
              <div>开发中</div>
              <small>后续将接入预测模型与文字描述</small>
            </div>
          </section>
        </aside>
      </div>

      {loading ? <div className="floating-tip">数据更新中...</div> : null}
      {error ? <div className="floating-error">{error}</div> : null}
    </div>
  );
}

export default App;
